            </select>
          </label>
          <label>
            Pick a place:{' '}
            <select value={placeId} onChange={e => {
              setPlaceId(e.target.value);
            }}>
              {placeList.map(place =>
                <option key={place.id} value={place.id}>{place.name}</option>
