      return (
        <label>
          <input
            type="checkbox"
            checked={task.done}
            onChange={e => {
              onChange({
                ...task,
                done: e.target.checked
              });
            }}
          />
          {taskContent}
          <button onClick={() => onDelete(task.id)}>
            Delete
          </button>
        </label>
