      return (
        <>
          <nav>
            <button onClick={handleScrollToFirstCat}>
              Neo
            </button>
            <button onClick={handleScrollToSecondCat}>
              Millie
            </button>
            <button onClick={handleScrollToThirdCat}>
              Bella
            </button>
          </nav>
          <div>
            <ul>
              <li>
