          <label>
            <input
              type="checkbox"
              checked={showB}
              onChange={e => {
                setShowB(e.target.checked)
              }}
            />
            Render the second counter
          </label>
        </div>
      );
    }

    function Counter() {
      const [score, setScore] = useState(0);
      const [hover, setHover] = useState(false);

