      const [isSent, setIsSent] = useState(false);
      const [message, setMessage] = useState('');

      if (isSent) {
        return <h1>Thank you!</h1>;
      }

      return (
        <form onSubmit={e => {
          e.preventDefault();
          alert(`Sending: "${message}"`);
          setIsSent(true);
        }}>
          <textarea
            placeholder="Message"
            value={message}
            onChange={e => setMessage(e.target.value)}
