                  title: e.target.value
                });
              }} />
            <button onClick={() => setIsEditing(false)}>
              Save
            </button>
          </>
        );
      } else {
        todoContent = (
          <>
            {todo.title}
            <button onClick={() => setIsEditing(true)}>
              Edit
            </button>
          </>
        );
      }
      return (
        <label>
          <input
            type="checkbox"
            checked={todo.done}
            onChange={e => {
              onChange({
                ...todo,
                done: e.target.checked
              });
            }}
          />
          {todoContent}
          <button onClick={() => onDelete(todo.id)}>
            Delete
          </button>
        </label>
      );
    }

