    .Row {
      border: 2px dashed black;
      padding: 5px;
      margin: 5px;
    }

This wouldn't work with Children.map because it would "see" <MoreRows /> as a single child (and a single row).

Accepting an array of objects as a prop

You can also explicitly pass an array as a prop. For example, this RowList accepts a rows array as a prop:

    import { RowList, Row } from './RowList.js';

    export default function App() {
      return (
        <RowList rows={[
          { id: 'first', content: <p>This is the first item.</p> },
          { id: 'second', content: <p>This is the second item.</p> },
          { id: 'third', content: <p>This is the third item.</p> }
        ]} />
      );
    }

src/RowList.js

    export function RowList({ rows }) {
      return (
        <div className="RowList">
          {rows.map(row => (
            <div className="Row" key={row.id}>
              {row.content}
            </div>
          ))}
        </div>
      );
    }

    .RowList {
      display: flex;
      flex-direction: column;
      border: 2px solid grey;
      padding: 5px;
    }

    .Row {
      border: 2px dashed black;
      padding: 5px;
      margin: 5px;
    }

Since rows is a regular JavaScript array, the RowList component can use built-in array methods like map on it.

This pattern is especially useful when you want to be able to pass more information as structured data together with children. In the below example, the TabSwitcher component receives an array of objects as the tabs prop:

    import TabSwitcher from './TabSwitcher.js';

    export default function App() {
      return (
        <TabSwitcher tabs={[
          {
            id: 'first',
            header: 'First',
            content: <p>This is the first item.</p>
          },
          {
            id: 'second',
            header: 'Second',
            content: <p>This is the second item.</p>
          },
          {
            id: 'third',
            header: 'Third',
            content: <p>This is the third item.</p>
          }
        ]} />
      );
    }

src/TabSwitcher.js

    import { useState } from 'react';

    export default function TabSwitcher({ tabs }) {
      const [selectedId, setSelectedId] = useState(tabs[0].id);
      const selectedTab = tabs.find(tab => tab.id === selectedId);
      return (
        <>
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setSelectedId(tab.id)}
            >
              {tab.header}
            </button>
          ))}
          <hr />
          <div key={selectedId}>
            <h3>{selectedTab.header}</h3>
            {selectedTab.content}
          </div>
        </>
      );
    }

Unlike passing the children as JSX, this approach lets you associate some extra data like header with each item. Because you are working with the tabs directly, and it is an array, you do not need the Children methods.

Calling a render prop to customize rendering

Instead of producing JSX for every single item, you can also pass a function that returns JSX, and call that function when necessary. In this example, the App component passes a renderContent function to the TabSwitcher component. The TabSwitcher component calls renderContent only for the selected tab:

    import TabSwitcher from './TabSwitcher.js';

    export default function App() {
      return (
        <TabSwitcher
          tabIds={['first', 'second', 'third']}
          getHeader={tabId => {
            return tabId[0].toUpperCase() + tabId.slice(1);
          }}
          renderContent={tabId => {
            return <p>This is the {tabId} item.</p>;
          }}
        />
      );
    }

src/TabSwitcher.js

    import { useState } from 'react';

    export default function TabSwitcher({ tabIds, getHeader, renderContent }) {
      const [selectedId, setSelectedId] = useState(tabIds[0]);
      return (
        <>
          {tabIds.map((tabId) => (
            <button
              key={tabId}
              onClick={() => setSelectedId(tabId)}
            >
              {getHeader(tabId)}
            </button>
          ))}
          <hr />
          <div key={selectedId}>
            <h3>{getHeader(selectedId)}</h3>
            {renderContent(selectedId)}
          </div>
        </>
      );
    }

A prop like renderContent is called a render prop because it is a prop that specifies how to render a piece of the user interface. However, there is nothing special about it: it is a regular prop which happens to be a function.

Render props are functions, so you can pass information to them. For example, this RowList component passes the id and the index of each row to the renderRow render prop, which uses index to highlight even rows:

    import { RowList, Row } from './RowList.js';

    export default function App() {
      return (
        <RowList
          rowIds={['first', 'second', 'third']}
          renderRow={(id, index) => {
            return (
              <Row isHighlighted={index % 2 === 0}>
                <p>This is the {id} item.</p>
              </Row>
            );
          }}
        />
      );
    }

src/RowList.js

    import { Fragment } from 'react';

    export function RowList({ rowIds, renderRow }) {
      return (
        <div className="RowList">
          <h1 className="RowListHeader">
            Total rows: {rowIds.length}
          </h1>
          {rowIds.map((rowId, index) =>
            <Fragment key={rowId}>
              {renderRow(rowId, index)}
            </Fragment>
          )}
        </div>
      );
    }

    export function Row({ children, isHighlighted }) {
      return (
        <div className={[
          'Row',
          isHighlighted ? 'RowHighlighted' : ''
        ].join(' ')}>
          {children}
        </div>
      );
    }

    .RowList {
      display: flex;
      flex-direction: column;
      border: 2px solid grey;
      padding: 5px;
    }

    .RowListHeader {
      padding-top: 5px;
      font-size: 25px;
      font-weight: bold;
      text-align: center;
    }

    .Row {
      border: 2px dashed black;
      padding: 5px;
      margin: 5px;
