Displaying validation errors and preserving form values

Return validation errors and submitted values from the Action to display an error without clearing the affected fields. Try submitting a name with fewer than three characters:

src/App.js

    import { useActionState } from 'react';
    import { updateName } from './api.js';

    const initialState = {
      error: null,
      submitted: null,
    };

    export default function UpdateName() {
      const [state, submitAction, isPending] = useActionState(
        updateName,
        initialState
      );

      return (
        <form action={submitAction}>
          <label>
            Name:{' '}
            <input
              name="name"
              defaultValue={state.submitted?.get('name') ?? ''}
              disabled={isPending}
            />
          </label>
          <button type="submit" disabled={isPending}>Save</button>
          {state.error && <p>{state.error}</p>}
        </form>
      );
    }

src/api.js

    export async function updateName(previousState, formData) {
      await new Promise(resolve => setTimeout(resolve, 1000));
      const name = formData.get('name');
      if (typeof name !== 'string' || name.trim().length < 3) {
        return {
          error: 'Name must be at least three characters long',
          submitted: formData,
        };
      }
      return {
        error: null,
        submitted: null,
      };
    }

When validation fails, updateName returns an error and the submitted FormData. The component uses the submitted name as the input's new defaultValue, so React's automatic form reset preserves it. When validation succeeds, submitted is null, so the automatic reset clears the field.

React Server Components

The example above runs updateName in the browser. To display the error and preserve the submitted name before JavaScript loads, make updateName a Server Function. Keep passing submitAction to the form's action prop. React can then display the Server Function's returned value before hydration completes. See preserving form values before JavaScript loads for the setup. On pages with dynamic content, you can also use the optional permalink parameter for progressive enhancement.

Handling errors

There are two ways to handle errors with useActionState.

For known errors, such as "quantity not available" validation errors from your backend, you can return it as part of your reducerAction state and display it in the UI.

For unknown errors, such as undefined is not a function, you can throw an error. React will cancel all queued Actions and show the nearest Error Boundary by rethrowing the error from the useActionState hook.

src/App.js

    import {useActionState, startTransition} from 'react';
    import {ErrorBoundary} from 'react-error-boundary';
    import {addToCart} from './api';
    import Total from './Total';

    function Checkout() {
      const [state, dispatchAction, isPending] = useActionState(
        async (prevState, quantity) => {
          const result = await addToCart(prevState.count, quantity);
          if (result.error) {
            // Return the error from the API as state
            return {...prevState, error: `Could not add quantity ${quantity}: ${result.error}`};
          }

          if (!isPending) {
            // Clear the error state for the first dispatch.
            return {count: result.count, error: null};
          }

          // Return the new count, and any errors that happened.
          return {count: result.count, error: prevState.error};

        },
        {
          count: 0,
          error: null,
        }
      );

      function handleAdd(quantity) {
        startTransition(() => {
          dispatchAction(quantity);
        });
      }

      return (
        <div className="checkout">
          <h2>Checkout</h2>
          <div className="row">
            <span>Eras Tour Tickets</span>
            <span>
              {isPending && '🌀 '}Qty: {state.count}
            </span>
          </div>
          <div className="buttons">
            <button onClick={() => handleAdd(1)}>Add 1</button>
            <button onClick={() => handleAdd(10)}>Add 10</button>
            <button onClick={() => handleAdd(NaN)}>Add NaN</button>
          </div>
          {state.error && <div className="error">{state.error}</div>}
          <hr />
          <Total quantity={state.count} isPending={isPending} />
        </div>
      );
    }

    export default function App() {
      return (
        <ErrorBoundary
          fallbackRender={({resetErrorBoundary}) => (
            <div className="checkout">
              <h2>Something went wrong</h2>
              <p>The action could not be completed.</p>
              <button onClick={resetErrorBoundary}>Try again</button>
            </div>
          )}>
          <Checkout />
        </ErrorBoundary>
      );
    }

