Solution

Scaling up with context and a reducer

In larger apps, it is common to combine context with a reducer to extract the logic related to some state out of components. In this example, all the "wiring" is hidden in the TasksContext.js, which contains a reducer and two separate contexts.

Read a full walkthrough of this example.

src/App.js

    import AddTask from './AddTask.js';
    import TaskList from './TaskList.js';
    import { TasksProvider } from './TasksContext.js';

    export default function TaskApp() {
      return (
        <TasksProvider>
          <h1>Day off in Kyoto</h1>
          <AddTask />
          <TaskList />
        </TasksProvider>
      );
    }

src/TasksContext.js

    import { createContext, useContext, useReducer } from 'react';

    const TasksContext = createContext(null);

    const TasksDispatchContext = createContext(null);

    export function TasksProvider({ children }) {
      const [tasks, dispatch] = useReducer(
        tasksReducer,
        initialTasks
      );

      return (
        <TasksContext value={tasks}>
          <TasksDispatchContext value={dispatch}>
            {children}
          </TasksDispatchContext>
        </TasksContext>
      );
    }

    export function useTasks() {
      return useContext(TasksContext);
    }

    export function useTasksDispatch() {
      return useContext(TasksDispatchContext);
    }

    function tasksReducer(tasks, action) {
      switch (action.type) {
        case 'added': {
          return [...tasks, {
            id: action.id,
            text: action.text,
            done: false
          }];
        }
        case 'changed': {
          return tasks.map(t => {
            if (t.id === action.task.id) {
              return action.task;
            } else {
              return t;
            }
          });
        }
        case 'deleted': {
          return tasks.filter(t => t.id !== action.id);
        }
        default: {
          throw Error('Unknown action: ' + action.type);
        }
      }
    }

    const initialTasks = [
      { id: 0, text: 'Philosopher’s Path', done: true },
      { id: 1, text: 'Visit the temple', done: false },
      { id: 2, text: 'Drink matcha', done: false }
    ];

src/AddTask.js

    import { useState } from 'react';
    import { useTasksDispatch } from './TasksContext.js';

    export default function AddTask() {
      const [text, setText] = useState('');
      const dispatch = useTasksDispatch();
      return (
        <>
          <input
            placeholder="Add task"
            value={text}
            onChange={e => setText(e.target.value)}
          />
          <button onClick={() => {
            setText('');
            dispatch({
              type: 'added',
              id: nextId++,
              text: text,
            });
          }}>Add</button>
        </>
      );
    }

    let nextId = 3;

src/TaskList.js

    import { useState } from 'react';
    import { useTasks, useTasksDispatch } from './TasksContext.js';

    export default function TaskList() {
      const tasks = useTasks();
      return (
        <ul>
          {tasks.map(task => (
            <li key={task.id}>
              <Task task={task} />
            </li>
          ))}
        </ul>
      );
    }

    function Task({ task }) {
      const [isEditing, setIsEditing] = useState(false);
      const dispatch = useTasksDispatch();
      let taskContent;
      if (isEditing) {
        taskContent = (
          <>
            <input
              value={task.text}
              onChange={e => {
                dispatch({
                  type: 'changed',
                  task: {
                    ...task,
                    text: e.target.value
                  }
                });
              }} />
            <button onClick={() => setIsEditing(false)}>
              Save
            </button>
          </>
        );
      } else {
        taskContent = (
          <>
            {task.text}
            <button onClick={() => setIsEditing(true)}>
              Edit
            </button>
          </>
        );
      }
      return (
        <label>
          <input
            type="checkbox"
            checked={task.done}
            onChange={e => {
              dispatch({
                type: 'changed',
                task: {
                  ...task,
                  done: e.target.checked
                }
              });
            }}
          />
          {taskContent}
          <button onClick={() => {
            dispatch({
              type: 'deleted',
              id: task.id
            });
          }}>
            Delete
          </button>
        </label>
      );
    }

    button { margin: 5px; }
    li { list-style-type: none; }
    ul, li { margin: 0; padding: 0; }

Solution

Specifying a fallback default value

If React can't find any providers of that particular context in the parent tree, the context value returned by useContext() will be equal to the default value that you specified when you created that context:

    const ThemeContext = createContext(null);

The default value never changes. If you want to update context, use it with state as described above.

Often, instead of null, there is some more meaningful value you can use as a default, for example:

    const ThemeContext = createContext('light');

This way, if you accidentally render some component without a corresponding provider, it won't break. This also helps your components work well in a test environment without setting up a lot of providers in the tests.

In the example below, the "Toggle theme" button is always light because it's outside any theme context provider and the default context theme value is 'light'. Try editing the default theme to be 'dark'.

    import { createContext, useContext, useState } from 'react';

    const ThemeContext = createContext('light');

    export default function MyApp() {
      const [theme, setTheme] = useState('light');
      return (
        <>
          <ThemeContext value={theme}>
            <Form />
          </ThemeContext>
          <Button onClick={() => {
            setTheme(theme === 'dark' ? 'light' : 'dark');
          }}>
            Toggle theme
          </Button>
        </>
      )
    }

    function Form({ children }) {
      return (
        <Panel title="Welcome">
          <Button>Sign up</Button>
          <Button>Log in</Button>
        </Panel>
      );
    }

    function Panel({ title, children }) {
      const theme = useContext(ThemeContext);
      const className = 'panel-' + theme;
      return (
        <section className={className}>
          <h1>{title}</h1>
          {children}
        </section>
      )
    }

    function Button({ children, onClick }) {
      const theme = useContext(ThemeContext);
      const className = 'button-' + theme;
      return (
        <button className={className} onClick={onClick}>
          {children}
        </button>
      );
    }

