              type="checkbox"
              checked={isDark}
              onChange={e => setIsDark(e.target.checked)}
            />
            Dark mode
          </label>
          <hr />
          <TodoList
            todos={todos}
            tab={tab}
            theme={isDark ? 'dark' : 'light'}
          />
        </>
      );
    }

