Solution

Avoiding recreating the initial state

React saves the initial state once and ignores it on the next renders.

    function createInitialState(username) {
      // ...
    }

    function TodoList({ username }) {
      const [state, dispatch] = useReducer(reducer, createInitialState(username));
      // ...

Although the result of createInitialState(username) is only used for the initial render, you're still calling this function on every render. This can be wasteful if it's creating large arrays or performing expensive calculations.

To solve this, you may pass it as an initializer function to useReducer as the third argument instead:

    function createInitialState(username) {
      // ...
    }

    function TodoList({ username }) {
      const [state, dispatch] = useReducer(reducer, username, createInitialState);
      // ...

Notice that you’re passing createInitialState, which is the function itself, and not createInitialState(), which is the result of calling it. This way, the initial state does not get re-created after initialization.

In the above example, createInitialState takes a username argument. If your initializer doesn't need any information to compute the initial state, you may pass null as the second argument to useReducer.

The difference between passing an initializer and passing the initial state directly

Passing the initializer function

This example passes the initializer function, so the createInitialState function only runs during initialization. It does not run when component re-renders, such as when you type into the input.

src/App.js

    import TodoList from './TodoList.js';

    export default function App() {
      return <TodoList username="Taylor" />;
    }

src/TodoList.js

    import { useReducer } from 'react';

    function createInitialState(username) {
      const initialTodos = [];
      for (let i = 0; i < 50; i++) {
        initialTodos.push({
          id: i,
          text: username + "'s task #" + (i + 1)
        });
      }
      return {
        draft: '',
        todos: initialTodos,
      };
    }

    function reducer(state, action) {
      switch (action.type) {
        case 'changed_draft': {
          return {
            draft: action.nextDraft,
            todos: state.todos,
          };
        };
        case 'added_todo': {
          return {
            draft: '',
            todos: [{
              id: state.todos.length,
              text: state.draft
            }, ...state.todos]
          }
        }
      }
      throw Error('Unknown action: ' + action.type);
    }

    export default function TodoList({ username }) {
      const [state, dispatch] = useReducer(
        reducer,
        username,
        createInitialState
      );
      return (
        <>
          <input
            value={state.draft}
            onChange={e => {
              dispatch({
                type: 'changed_draft',
                nextDraft: e.target.value
              })
            }}
          />
          <button onClick={() => {
            dispatch({ type: 'added_todo' });
          }}>Add</button>
          <ul>
            {state.todos.map(item => (
              <li key={item.id}>
                {item.text}
              </li>
            ))}
          </ul>
        </>
      );
    }

