      return (
        <div className="total">
          <span>Total:</span>
          <div>
            <div>
              {isPending
                ? "🌀 Updating..."
                : `${intl.format(savedQuantity * 9999)}`}
            </div>
            <div className="error">
              {!isPending &&
                clientQuantity !== savedQuantity &&
                `Wrong total, expected: ${intl.format(clientQuantity * 9999)}`}
            </div>
          </div>
        </div>
      );
    }

